def solve(n, s):
    if n % 2 != 0:
        return ":("

    open_count = 0
    close_count = 0
    question_count = s.count('?')

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            close_count += 1

    if open_count + question_count < n // 2 or close_count + question_count < n // 2:
        return ":("

    result = list(s)
    open_needed = n // 2 - open_count

    for i in range(n):
        if result[i] == '?':
            if open_needed > 0:
                result[i] = '('
                open_needed -= 1
            else:
                result[i] = ')'

    open_count = 0
    close_count = 0
    for i in range(n):
        if result[i] == '(':
            open_count += 1
        elif result[i] == ')':
            close_count += 1
        if open_count <= close_count:
            return ":("

    if open_count != close_count:
        return ":("

    return ''.join(result)

